let show = function None -> "none" | Some n -> "some " ^ string_of_int n
let () =
  print_endline (show (first_even [1; 3; 4; 6]));
  print_endline (show (first_even [1; 3]));
  Printf.printf "%d\n" (Option.value (first_even [1; 3]) ~default:0);
  Option.iter (Printf.printf "%d\n") (Option.map (fun n -> n * 10) (first_even [2]))

