type day = Mon | Tue | Wed | Thu | Fri | Sat | Sun

let kind = function Sat | Sun -> "weekend" | _ -> "weekday"

let classify n =
  match n with
  | 0 -> "zero"
  | n when n < 0 -> "negative"
  | n when n mod 2 = 0 -> "even"
  | _ -> "odd"

let dup_head = function (x :: _) as whole -> x :: whole | [] -> []

let () =
  List.iter (fun d -> print_endline (kind d)) [Mon; Sat];
  List.iter (fun n -> print_endline (classify n)) [0; -3; 4; 7];
  List.iter (Printf.printf "%d ") (dup_head [9; 8]);
  print_newline ()
